class Solution:
    def licenseKeyFormatting(self, s: str, k: int) -> str:
        t = s.replace('-', '').upper()
        n = len(t)
        if n == 0:
            return ""
        first = n % k or k
        parts = [t[:first]]
        for i in range(first, n, k):
            parts.append(t[i:i+k])
        return '-'.join(parts)
```

