import random
from typing import List
from collections import defaultdict

class Solution:

    def __init__(self, nums: List[int]):
        self.pos = defaultdict(list)
        for i, v in enumerate(nums):
            self.pos[v].append(i)

    def pick(self, target: int) -> int:
