Approach: build a trie of the reversed words. On each query, append the letter to the stream, then walk the trie backward from the newest character. Return true as soon as we reach a node that ends a word.

- Only the last `maxLen` characters can ever matter, so the stream is a `deque` capped at the maximum word length.
- Each query costs at most O(200) trie steps.

```python
from typing import List
from collections import deque

class StreamChecker:

    def __init__(self, words: List[str]):
        self.trie = {}
        self.maxlen = 0
        for w in words:
            node = self.trie
            for ch in reversed(w):
                node = node.setdefault(ch, {})
            node['$'] = True
            if len(w) > self.maxlen:
                self.maxlen = len(w)
        self.stream = deque(maxlen=self.maxlen)

    def query(self, letter: str) -> bool:
        self.stream.append(letter)
        node = self.trie
        for i in range(len(self.stream) - 1, -1, -1):
            ch = self.stream[i]
            if ch not in node:
                return False
            node = node[ch]
            if '$' in node:
                return True
        return False


# Your StreamChecker object will be instantiated and called as such:
# obj = StreamChecker(words)
# param_1 = obj.query(letter)
```

