class Solution:
    def isSolvable(self, words: List[str], result: str) -> bool:
        words = [w.strip() for w in words]
        result = result.strip()
        L = len(result)
        if any(len(w) > L for w in words):
            return False
        lead = set()
        for w in words + [result]:
            if len(w) > 1:
                lead.add(w[0])
        assign = {}
        used = [False] * 10
        n = len(words)

        def dfs(col, row, s):
            if col == L:
                return s == 0
            if row == n:
                d = s % 10
                c = result[L - 1 - col]
                if c in assign:
                    if assign[c] != d:
                        return False
                    return dfs(col + 1, 0, s // 10)
                if used[d] or (d == 0 and c in lead):
                    return False
                assign[c] = d
                used[d] = True
                ok = dfs(col + 1, 0, s // 10)
                del assign[c]
                used[d] = False
                return ok
            w = words[row]
            if col >= len(w):
                return dfs(col, row + 1, s)
            c = w[len(w) - 1 - col]
            if c in assign:
                return dfs(col, row + 1, s + assign[c])
            for d in range(10):
                if used[d] or (d == 0 and c in lead):
                    continue
                assign[c] = d
                used[d] = True
                if dfs(col, row + 1, s + d):
                    del assign[c]
                    used[d] = False
                    return True
                del assign[c]
                used[d] = False
            return False

        return dfs(0, 0, 0)
